-- Check 1 can finally see the residuary.
--
-- Measured 2026-09-10, and this version exists because of it. The audit
-- resolved `design_sheet.residuary_beneficiary` — a column empty on all 44
-- latest sheets and never written by anything. `ResiduarySection.tsx` writes
-- the residuary somewhere else entirely: into a jsonb blob, under
-- `residuary_spouse_survives` and `residuary_no_spouse`.
--
-- So check 1 asked "is a residuary recorded?", looked at the wrong place, and
-- raised nine blocker findings. SEVEN of the nine were against matters that
-- had one: 0528d2db, 10904a59, 48aac2c1, 590a0498, d11717cd, e10908ee,
-- fadd6263. All seven were archived as false on 2026-09-10.
--
-- 20261121000000 moved that data into `design_sheets.decisions`, and the
-- allow-list gained a `jsonKey` form so a declared input can name a key
-- inside a jsonb column. This version declares the two inputs and adds them
-- to check 1's reads.
--
-- NOT A STATEMENT CHANGE. Every check's statement is byte-identical to
-- version 9 — asserted while generating this file, not trusted to this
-- comment. What changed is what check 1 can see, not what it is asked. The
-- old `residuary_*` column inputs stay: those fields are intended, and the
-- intake will populate them once the template work lands.

insert into public.prompt_versions (
  prompt_id, kind, version_number, body, content_hash, change_summary, validation_status
)
select
  p.id,
  'field_audit',
  10,
  '{"kind":"field_audit","outputTarget":"checklist","inputs":[{"key":"concerns","source":"design_sheet.concerns","required":true},{"key":"goals_notes","source":"design_sheet.goals_notes","required":false},{"key":"drafting_notes","source":"design_sheet.drafting_notes","required":false},{"key":"children","source":"design_sheet.children","required":false},{"key":"assets","source":"design_sheet.assets","required":false},{"key":"specific_bequests","source":"design_sheet.specific_bequests","required":false},{"key":"disinheritances","source":"design_sheet.disinheritances","required":false},{"key":"residuary_beneficiary","source":"design_sheet.residuary_beneficiary","required":false},{"key":"residual_beneficiary_individuals","source":"design_sheet.residual_beneficiary_individuals","required":false},{"key":"residuary_distribution","source":"design_sheet.residuary_distribution","required":false},{"key":"spouse_citizenship","source":"design_sheet.spouse_citizenship","required":false},{"key":"include_qdot","source":"design_sheet.include_qdot","required":false},{"key":"marital_trust_type","source":"design_sheet.marital_trust_type","required":false},{"key":"real_property_transfer","source":"design_sheet.real_property_transfer","required":false},{"key":"state","source":"design_sheet.state","required":false},{"key":"client_domicile","source":"design_sheet.client_domicile","required":false},{"key":"guardian_primary","source":"design_sheet.guardian_primary","required":false},{"key":"guardian_alt1","source":"design_sheet.guardian_alt1","required":false},{"key":"trustee_primary","source":"design_sheet.trustee_primary","required":false},{"key":"trustee_alt1","source":"design_sheet.trustee_alt1","required":false},{"key":"executor_primary","source":"design_sheet.executor_primary","required":false},{"key":"hcp_primary","source":"design_sheet.hcp_primary","required":false},{"key":"poa_primary","source":"design_sheet.poa_primary","required":false},{"key":"spouse_name","source":"design_sheet.spouse_name","required":false},{"key":"client_name","source":"design_sheet.client_name","required":false},{"key":"guardian_slots","source":"design_sheet.guardian_slots","required":false},{"key":"temporary_guardian_slots","source":"design_sheet.temporary_guardian_slots","required":false},{"key":"trustee_slots","source":"design_sheet.trustee_slots","required":false},{"key":"executor_slots","source":"design_sheet.executor_slots","required":false},{"key":"hcp_slots","source":"design_sheet.hcp_slots","required":false},{"key":"poa_slots","source":"design_sheet.poa_slots","required":false},{"key":"residuary_spouse_survives","source":"design_sheet.residuary_spouse_survives","required":false},{"key":"residuary_no_spouse","source":"design_sheet.residuary_no_spouse","required":false}],"checks":[{"number":"1","risk":"blocker","reads":["concerns","goals_notes","residuary_beneficiary","residual_beneficiary_individuals","residuary_distribution","marital_trust_type","guardian_primary","guardian_alt1","trustee_primary","trustee_alt1","executor_primary","hcp_primary","poa_primary","guardian_slots","temporary_guardian_slots","trustee_slots","executor_slots","hcp_slots","poa_slots","residuary_spouse_survives","residuary_no_spouse"],"statement":"Every concern the client stated has a provision in the plan responsive to it — a residuary that reflects it, a trust type that accommodates it, a fiduciary appointed to carry it out. A concern need not be phrased as a goal. An asset the client described is a concern: property recorded with nothing directing where it goes is precisely the gap this check exists to find, and an empty goals_notes is not a reason to pass. Do not require the client to have written \"avoid probate\" or \"provide for the children\" before a missing residuary counts. Report the substance only: whether the plan does the thing the concern asks for. A person named in the concerns who appears nowhere in the structured decisions is check 2''s finding and not this one; reporting it here as well raises two blockers for one gap, and an attorney reading a list of two learns less than one who reads a list of one.","taskTemplate":{"title":"A stated concern is not answered by the plan","description":"The design sheet records a concern the plan makes no provision for. Confirm whether the plan should change or the concern is answered elsewhere. If the concern is that a named person is missing, that is a separate finding.","priority":"high"}},{"number":"2","risk":"blocker","reads":["concerns","goals_notes","drafting_notes","children","residual_beneficiary_individuals","residuary_beneficiary","guardian_primary","guardian_alt1","trustee_primary","trustee_alt1","executor_primary","hcp_primary","poa_primary","spouse_name","client_name","guardian_slots","temporary_guardian_slots","trustee_slots","executor_slots","hcp_slots","poa_slots"],"statement":"Every person whose name appears in the client''s free text — concerns, goals_notes or drafting_notes — also appears somewhere in the structured decisions. The name must be written in that free text to be in scope: a category such as \"descendants\", \"my children\" or \"issue\" names nobody. A name is in scope only where the client wrote it as someone the plan should provide for or appoint. A third party identified by their professional relationship to an asset or to the file — the agent who wrote a policy, the accountant who prepares the returns, the bank holding an account, whoever referred the client — is not a person the instrument omits, and their absence from the structured decisions is not a finding. The test is why the name is there, not what the person does: anyone the client named for a role, whether a beneficiary, a fiduciary, a successor or an alternate, is in scope however they are described, including where the description is a profession. A relative introduced as \"my brother the accountant\" is in scope exactly as any relative is. The direction is one-way. Free text → structured decisions, never the reverse. A person who appears in the structured decisions but not in the free text is not a finding and never was: a trustee, guardian or executor recorded in a slot and nowhere else is the ordinary case, not an omission. If you find yourself asking whether a name in a fiduciary slot appears in the concerns, you are auditing the wrong direction — stop, and answer the question in the first sentence. \"Appears in the structured decisions\" means any of them — a beneficiary field, a fiduciary field, spouse_name or client_name all count; a person need not be a beneficiary to be captured. Report only this: a person the client wrote by name whom the structured decisions never mention, who will therefore be absent from the drafted instrument with nobody noticing until it is signed. Whether the plan records a provision the concerns ask for — a residuary reflecting the client''s intent, for instance — is check 1''s finding and not this one, even when the fields it would live in are empty.","taskTemplate":{"title":"A person named in the notes is missing from the plan","description":"Someone is named in the design sheet''s free text but appears in none of the beneficiary or fiduciary fields. Confirm whether they were meant to be included.","priority":"high"}},{"number":"3","risk":"high","reads":["specific_bequests","assets"],"statement":"Every specific bequest names something the asset list contains. A bequest of property the client does not own, or no longer owns, adeems — the beneficiary takes nothing, and the gift the client believed they had made silently fails.","taskTemplate":{"title":"A specific bequest names an asset not on the list","description":"A specific bequest refers to property the asset list does not record. Confirm ownership before drafting, or the gift may adeem.","priority":"normal"}},{"number":"4","risk":"high","reads":["disinheritances","residuary_beneficiary","residual_beneficiary_individuals","concerns"],"statement":"Every disinheritance is deliberate on its face and consistent with the residuary. An omission that reads as accidental invites a pretermitted-heir claim under MUPC c. 190B § 2-302, and a person recorded as disinherited who nonetheless appears among the residuary beneficiaries is a contradiction the drafting cannot resolve.","taskTemplate":{"title":"A disinheritance is unclear or contradicted","description":"The disinheritance record either states no reason or conflicts with the residuary. Confirm the intent and make the omission explicit in the drafting.","priority":"normal"}},{"number":"5","risk":"blocker","reads":["spouse_citizenship","include_qdot","marital_trust_type"],"statement":"A spouse who is not a United States citizen has a QDOT, or a recorded decision not to use one. IRC § 2056(d) denies the unlimited marital deduction outright for a non-citizen spouse absent a qualified domestic trust, and the citizenship field is free text where ''green card'', ''permanent resident'' and ''not a citizen'' all appear and all mean the same thing here.","taskTemplate":{"title":"Non-citizen spouse with no QDOT decision","description":"The spouse appears not to be a US citizen and no QDOT decision is recorded. IRC 2056(d) denies the marital deduction without one.","priority":"high"}},{"number":"6","risk":"high","reads":["assets","real_property_transfer","state","client_domicile"],"statement":"Every parcel of real property recorded in the assets field has a transfer decision, and property outside Massachusetts has a plan for it. The asset list is the whole subject: if assets records no real property — including when it is empty — this check does not apply. Real property described only in the concerns or the notes is not a parcel in the asset list; that the sheet records no asset the concerns describe is check 1''s finding, not this one. Reporting it here cites two empty fields as though they were a parcel and its missing decision, which verifies and supports nothing. A trust that does not hold the house is the failure the funding tracker exists to catch, one stage earlier; and a Massachusetts trust alone does not avoid ancillary probate in the state where the other property sits.","taskTemplate":{"title":"Real property with no transfer decision","description":"The asset list records real property with no transfer decision, or property outside Massachusetts with no ancillary plan. Confirm how each parcel reaches the trust.","priority":"high"}}]}'::jsonb,
  'b645a041a7c187806a2860268c84c6e098611f46d1a6875105353f70a06ea862',
  'Check 1 reads the residuary where ResiduarySection actually writes it: two decisions-blob inputs, no statement changed.',
  'valid'
from public.prompts p
where p.slug = 'ma-design-sheet-audit'
on conflict (prompt_id, version_number) do nothing;

insert into public.prompt_publications (prompt_id, version_id)
select v.prompt_id, v.id
from public.prompt_versions v
join public.prompts p on p.id = v.prompt_id
where p.slug = 'ma-design-sheet-audit' and v.version_number = 10
on conflict (prompt_id) do update set version_id = excluded.version_id, published_at = now();
